mapper.select:
SELECT
FACTORY_CODE,
MOULD_CODE,
MATERIAL_CODE,
MES_MATERIAL_CODE,
SPEC_DESC,
PATTERN,
REMARK,
DEL_FLAG,
DATA_VERSION,
SAME_PATTER_PANEL,
MOULD_TYPE
FROM PRODUCT_MOD_RELATION
WHERE DEL_FLAG = 0
AND FACTORY_CODE = #{factoryCode}
AND MOULD_CODE = #{mouldCode}
AND MATERIAL_CODE = #{materialCode}
AND MES_MATERIAL_CODE = #{mesMaterialCode}
AND SPEC_DESC = #{materialDesc}
AND PATTERN = #{pattern}
AND DATA_VERSION = #{dataVersion}
AND SAME_PATTER_PANEL = #{samePatternPanel}
AND MOULD_TYPE = #{mouldType}

SELECT
FACTORY_CODE,
MOULD_CODE,
MOULD_STATUS,
LOGISTICS_STATUS,
SPECIFICATIONS,
PATTERN,
MOULD_SHELL_STANDARD,
BRAND,
MOULD_TYPE,
MAIN_TRADEMARK,
MOULD_REMARK,
MOULD_SLEEVE,
MOULD_AIR_TYPE,
DEL_FLAG,
DATA_VERSION
FROM TIRE_MOD_INFO
WHERE DEL_FLAG = 0
AND FACTORY_CODE = #{factoryCode}
AND MOULD_CODE = #{mouldCode}
AND MOULD_STATUS = #{mouldStatus}
AND LOGISTICS_STATUS = #{logisticsStatus}
AND SPECIFICATIONS = #{specifications}
AND PATTERN = #{pattern}
AND BRAND = #{brand}
AND MOULD_TYPE = #{mouldType}
AND MAIN_TRADEMARK = #{mainTrademark}
AND MOULD_SLEEVE = #{mouldSleeve}
AND MOULD_AIR_TYPE = #{mouldAirType}
AND DATA_VERSION = #{dataVersion}
